import axios from 'axios';
import Cookies from 'js-cookie';

const instance = axios.create({
  baseURL: process.env.REACT_APP_API_URL || `http://127.0.0.1:8001/api`,
  timeout: 50000,
  headers: {
    Accept: 'application/json',
    'Content-Type': 'application/json',
  },
});


instance.interceptors.request.use(function (config) {
  const isAuthenticated = localStorage.getItem('token');
  //console.log("TOKEN ====>>", token);

  if (isAuthenticated && !config.headers['Authorization']) {
    config.headers['Authorization'] = `Bearer ${isAuthenticated}`;
  }

  return config;
}, function (error) {
  // Handle request errors
  return Promise.reject(error);
});

// Response Interceptor
instance.interceptors.response.use(
  response => response, // If response is successful, return it
  error => {
    if (error.response && error.response.status === 401) {
      // Clear authentication data (cookies/localStorage)
      localStorage.removeItem('authToken');
      localStorage.removeItem('token');
      localStorage.removeItem('userData');
      Cookies.remove('authToken');

      if (window.location.pathname !== '/') {
        window.location.href = '/';
      }

      // Optionally, you can redirect to the login page
    }
    return Promise.reject(error);
  }
);

const responseBody = (response) => response.data;

const requests = {
  get: (url, body, headers) =>
    instance.get(url, body, headers).then(responseBody),

  post: (url, body) => instance.post(url, body).then(responseBody),
  uploadPosts: (url, body) => instance.post(url, body, {
    headers: {
      'Content-Type': 'multipart/form-data',
    },
  }).then(responseBody),

  customPost: (url, body, token) => {
    return instance.post(url, body, {
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${token}`,
      }
    }).then(responseBody);
  },

  put: (url, body) =>
    instance.put(url, body).then(responseBody),

  patch: (url, body) => instance.patch(url, body).then(responseBody),

  delete: (url, body) => instance.delete(url, body).then(responseBody),
  upload: (url, formData) =>
    instance.post(url, formData, {
      headers: {
        'Content-Type': 'multipart/form-data',
      },
    }).then(responseBody),
};

export default requests;
